with flattened as (select id, customer_id, created_at, coupon_codes, k, attr_value from carts lateral view outer explode(attributes) e as k, attr_value), lines as (select customer_id, created_at, explode_outer(coupon_codes) as code from flattened), joined as (select s.*, p.signup_date, p.age from lines s left join customers p on s.customer_id = p.id), joined_carts as (select e.*, d.age as customer_age from joined e join customers d on e.customer_id = d.id), summary as (select customer_id, max(customer_age) filter (where code = 'BUNDLE') as bundle_max_customer_age, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, max(created_at) as ended_at from joined_carts group by customer_id having max(customer_age) filter (where code = 'BUNDLE') > 0) select s.customer_id, s.bundle_max_customer_age, s.ended_at, (select max(s2.monthly_fee) from subscriptions s2 where s2.customer_id = s.customer_id) as max_subscription_monthly_fee from summary s;
